├─ pom.xml
└─ src/main/
  ├─ resources/
  │ └─ application.properties
  └─ java/com/starplex/cinema/
    ├─ CinemaApplication.java
    ├─ Screen.java
    ├─ Show.java
    ├─ Repositories.java
    └─ CinemaRunner.java
```

