├─ pom.xml
└─ src/main/
   ├─ java/com/threadhouse/shop/
   │  ├─ CatalogueApplication.java
   │  ├─ Product.java
   │  └─ ProductRepository.java
   └─ resources/
      └─ application.properties
```

